INSERT INTO `locales_item` VALUES (19237, 'Sayge\'s Fortune #19', '세이지의 점괘 #19', 'Prédiction de Sayge n°19', 'Sayges Horoskop Nr. 19', '塞格的塔罗牌#19', '賽吉的占卜#19', 'Fortuna de Sayge n.º 19', 'Fortuna de Sayge n.º 19', 'Предсказание Воржея #19', 'The Forsaken are up to something.', '포세이큰이 흉계를 꾸미고 있느니 늘 경계하라.', 'Les Réprouvés trament quelque chose.', '', '被遗忘者有一些秘密的计划。', '被遺忘者有一些秘密的計畫。', 'Los Renegados planean algo.', 'Los Renegados planean algo.', 'Отрекшиеся что-то замышляют.');
INSERT INTO `locales_item` VALUES (19238, 'Sayge\'s Fortune #3', '세이지의 점괘 #3', 'Prédiction de Sayge n°3', 'Sayges Horoskop Nr. 3', '塞格的塔罗牌#3', '賽吉的占卜#3', 'Fortuna de Sayge n.º 3', 'Fortuna de Sayge n.º 3', 'Предсказание Воржея #3', 'An enemy from your past will soon become an ally.', '과거의 적이 내일의 동지가 되리라.', 'Un ennemi de votre passé deviendra bientôt un allié.', '', '过去的敌人将是未来的朋友。', '過去的敵人將是未來的朋友。', 'Un enemigo del pasado pronto se convertirá en un aliado.', 'Un enemigo del pasado pronto se convertirá en un aliado.', 'Бывший враг скоро станет союзником.');
INSERT INTO `locales_item` VALUES (19239, 'Sayge\'s Fortune #4', '세이지의 점괘 #4', 'Prédiction de Sayge n°4', 'Sayges Horoskop Nr. 4', '塞格的塔罗牌#4', '賽吉的占卜#4', 'Fortuna de Sayge n.º 4', 'Fortuna de Sayge n.º 4', 'Предсказание Воржея #4', 'You will be fortunate in everything you put your hands to.', '당신의 모든 일이 번창하리라.', 'Vous aurez de la chance dans tout ce que vous ferez.', '', '万事顺意。', '萬事順意。', 'Tendrás buena fortuna con cualquier empresa que acometas.', 'Tendrás buena fortuna con cualquier empresa que acometas.', 'Тебе будет везти во всех начинаниях.');
INSERT INTO `locales_item` VALUES (19240, 'Sayge\'s Fortune #5', '세이지의 점괘 #5', 'Prédiction de Sayge n°5', 'Sayges Horoskop Nr. 5', '塞格的塔罗牌#5', '賽吉的占卜#5', 'Fortuna de Sayge n.º 5', 'Fortuna de Sayge n.º 5', 'Предсказание Воржея #5', 'Someone is speaking well of you.', '누군가가 당신을 칭찬하느니라.', 'Quelqu\'un dit du bien de vous.', '', '有人很欣赏你。', '有人很欣賞你。', 'Alguien habla bien de ti.', 'Alguien habla bien de ti.', 'Кто-то очень хорошего о тебе мнения.');
INSERT INTO `locales_item` VALUES (19241, 'Sayge\'s Fortune #6', '세이지의 점괘 #6', 'Prédiction de Sayge n°6', 'Sayges Horoskop Nr. 6', '塞格的塔罗牌#6', '賽吉的占卜#6', 'Fortuna de Sayge n.º 6', 'Fortuna de Sayge n.º 6', 'Предсказание Воржея #6', 'Be cautious when landing in unfamiliar territory.', '적 진영에 착륙할 때는 항상 경계하라.', 'Soyez prudent quand vous atterrissez dans un territoire inconnu.', '', '出门在外，多加小心。', '出門在外，多加小心。', 'Cuidado cuando aterrices en terreno desconocido.', 'Cuidado cuando aterrices en terreno desconocido.', 'Будь осторожен, приземляясь на незнакомой территории.');
INSERT INTO `locales_item` VALUES (19242, 'Sayge\'s Fortune #7', '세이지의 점괘 #7', 'Prédiction de Sayge n°7', 'Sayges Horoskop Nr. 7', '塞格的塔罗牌#7', '賽吉的占卜#7', 'Fortuna de Sayge n.º 7', 'Fortuna de Sayge n.º 7', 'Предсказание Воржея #7', 'Avoid taking unnecessary gambles.', '불필요한 도박을 피하라.', 'Évitez de faire des paris inutiles.', '', '不要参与无把握的赌博。', '不要參與無把握的賭博。', 'Evita tomar riesgos innecesarios.', 'Evita tomar riesgos innecesarios.', 'Избегай лишнего риска.');
INSERT INTO `locales_item` VALUES (19243, 'Sayge\'s Fortune #8', '세이지의 점괘 #8', 'Prédiction de Sayge n°8', 'Sayges Horoskop Nr. 8', '塞格的塔罗牌#8', '賽吉的占卜#8', 'Fortuna de Sayge n.º 8', 'Fortuna de Sayge n.º 8', 'Предсказание Воржея #8', 'You will receive a fortune.', '큰 부를 누리게 되리라.', 'Vous recevrez une grande fortune.', '', '你将得到财富。', '你將會獲得一筆財富。', 'Recibirás una fortuna.', 'Recibirás una fortuna.', 'Вас ждет наследство.');
INSERT INTO `locales_item` VALUES (19244, 'Sayge\'s Fortune #9', '세이지의 점괘 #9', 'Prédiction de Sayge n°9', 'Sayges Horoskop Nr. 9', '塞格的塔罗牌#9', '賽吉的占卜#9', 'Fortuna de Sayge n.º 9', 'Fortuna de Sayge n.º 9', 'Предсказание Воржея #9', 'Your first love and last love is self-love.', '첫사랑이자 마지막 사랑은 자기 사랑이니라.', 'Votre premier et dernier amour reste l\'amour de vous-même.', '', '最忠诚的爱，就是爱自己。', '最忠誠的愛，就是愛自己。', 'Tu primer y último amor es el amor propio.', 'Tu primer y último amor es el amor propio.', 'Первая и последняя любовь – это всегда любовь к себе.');
INSERT INTO `locales_item` VALUES (19245, 'Sayge\'s Fortune #10', '세이지의 점괘 #10', 'Prédiction de Sayge n°10', 'Sayges Horoskop Nr. 10', '塞格的塔罗牌#10', '賽吉的占卜#10', 'Fortuna de Sayge n.º 10', 'Fortuna de Sayge n.º 10', 'Предсказание Воржея #10', 'Rest is a good thing, but boredom is its brother.', '여유로운 휴식은 달콤하지만 곧 권태가 따르리라.', 'Le repos est une bonne chose, mais l\'ennui est son frère.', '', '休息是好的，但疲倦是他的兄弟。', '休息是好的，但疲倦是他的兄弟。', 'El descanso es bueno, pero primo del aburrimiento.', 'El descanso es bueno, pero primo del aburrimiento.', 'От отдыха до скуки один шаг.');
INSERT INTO `locales_item` VALUES (19246, 'Sayge\'s Fortune #11', '세이지의 점괘 #11', 'Prédiction de Sayge n°11', 'Sayges Horoskop Nr. 11', '塞格的塔罗牌#11', '賽吉的占卜#11', 'Fortuna de Sayge n.º 11', 'Fortuna de Sayge n.º 11', 'Предсказание Воржея #11', 'Those with simple tastes are always satisfied with the best.', '취향이 단순한 자들은 언제나 최상의 것에 만족한다.', 'Les gens aux goûts simples sont toujours satisfaits par ce qu\'il y a de meilleur.', '', '简单就是美。', '簡單就是美。', 'Aquellos de gustos sencillos siempre se satisfacen con lo mejor.', 'Aquellos de gustos sencillos siempre se satisfacen con lo mejor.', 'Люди с непритязательным вкусом как правило довольствуются лучшим.');
INSERT INTO `locales_item` VALUES (19247, 'Sayge\'s Fortune #12', '세이지의 점괘 #12', 'Prédiction de Sayge n°12', 'Sayges Horoskop Nr. 12', '塞格的塔罗牌#12', '賽吉的占卜#12', 'Fortuna de Sayge n.º 12', 'Fortuna de Sayge n.º 12', 'Предсказание Воржея #12', 'Let not the tides of war wash you away.', '전세에 휩쓸리지 말지어다.', 'Ne laissez pas le tourbillon de la guerre vous balayer.', '', '不要让战争的潮水将你淹没。', '不要讓戰爭的潮水將你淹沒。', 'Que la marea de la guerra no te arrastre.', 'Que la marea de la guerra no te arrastre.', 'Барабаны войны да не оглушат тебя!');
INSERT INTO `locales_item` VALUES (19248, 'Sayge\'s Fortune #13', '세이지의 점괘 #13', 'Prédiction de Sayge n°13', 'Sayges Horoskop Nr. 13', '塞格的塔罗牌#13', '賽吉的占卜#13', 'Fortuna de Sayge n.º 13', 'Fortuna de Sayge n.º 13', 'Предсказание Воржея #13', 'You leave your adversaries speechless.', '적이 할말을 잃게 만들어라.', 'Vous laisserez vos adversaires sans voix.', '', '你让你的敌人永远闭嘴。', '你讓你的敵人永遠閉嘴。', 'Dejas a tus adversarios sin habla.', 'Dejas a tus adversarios sin habla.', 'Вы заставляете противников неметь.');
INSERT INTO `locales_item` VALUES (19249, 'Sayge\'s Fortune #14', '세이지의 점괘 #14', 'Prédiction de Sayge n°14', 'Sayges Horoskop Nr. 14', '塞格的塔罗牌#14', '賽吉的占卜#14', 'Fortuna de Sayge n.º 14', 'Fortuna de Sayge n.º 14', 'Предсказание Воржея #14', 'You have a good eye for spotting hypocrisy.', '위선을 간파하는 식견을 지녔도다.', 'Vous avez le coup d\'œil pour repérer l\'hypocrisie.', '', '伪善在你面前原形毕露。', '偽善在你面前原形畢露。', 'Enseguida cazas a los hipócritas.', 'Enseguida cazas a los hipócritas.', 'Ты всегда распознаешь лицемерие.');
INSERT INTO `locales_item` VALUES (19250, 'Sayge\'s Fortune #15', '세이지의 점괘 #15', 'Prédiction de Sayge n°15', 'Sayges Horoskop Nr. 15', '塞格的塔罗牌#15', '賽吉的占卜#15', 'Fortuna de Sayge n.º 15', 'Fortuna de Sayge n.º 15', 'Предсказание Воржея #15', 'One learns most when teaching others.', '남을 가르칠 때 진정한 깨달음을 얻으리라.', 'C\'est en enseignant qu\'on apprend le plus.', '', '教给别人越多，自己学得越多。', '教給別人越多，自己學得越多。', 'Nunca aprenderás más que al enseñar a otros.', 'Nunca aprenderás más que al enseñar a otros.', 'Лучше всего учишься, когда учишь другого.');
INSERT INTO `locales_item` VALUES (19251, 'Sayge\'s Fortune #16', '세이지의 점괘 #16', 'Prédiction de Sayge n°16', 'Sayges Horoskop Nr. 16', '塞格的塔罗牌#16', '賽吉的占卜#16', 'Fortuna de Sayge n.º 16', 'Fortuna de Sayge n.º 16', 'Предсказание Воржея #16', 'The time will soon come for you to make a choice in a pressing matter.', '곧 중대한 결정을 내려야 할 때가 닥치리라.', 'Vous devrez bientôt prendre une décision dans une affaire urgente.', '', '考验你的时刻即将到来。', '考驗你的時刻即將到來。', 'Pronto tendrás que tomar una decisión sobre un tema apremiante.', 'Pronto tendrás que tomar una decisión sobre un tema apremiante.', 'Скоро придется принимать решение в одном безотлагательном деле.');
INSERT INTO `locales_item` VALUES (19252, 'Sayge\'s Fortune #18', '세이지의 점괘 #18', 'Prédiction de Sayge n°18', 'Sayges Horoskop Nr. 18', '塞格的塔罗牌#18', '賽吉的占卜#18', 'Fortuna de Sayge n.º 18', 'Fortuna de Sayge n.º 18', 'Предсказание Воржея #18', 'Accept the next proposition you hear.', '다음에 듣게 될 제안은 무조건 수락하라.', 'Acceptez la prochaine proposition que l\'on vous fera.', '', '接受你听到的下一个建议。', '接受你聽到的下一個建議。', 'Acepta la siguiente proposición que oigas.', 'Acepta la siguiente proposición que oigas.', 'Прими первое услышанное предложение.');
INSERT INTO `locales_item` VALUES (19253, 'Sayge\'s Fortune #17', '세이지의 점괘 #17', 'Prédiction de Sayge n°17', 'Sayges Horoskop Nr. 17', '塞格的塔罗牌#17', '賽吉的占卜#17', 'Fortuna de Sayge n.º 17', 'Fortuna de Sayge n.º 17', 'Предсказание Воржея #17', 'Never punt a gnome without due cause.', '무턱대고 노움과 도박하지 말라.', 'Ne pariez jamais avec un gnome sans de bonnes raisons.', '', '不要随便踢侏儒。', '不要隨便踢地精。', 'Nunca patees a un gnomo sin razón.', 'Nunca patees a un gnomo sin razón.', 'И трогать гнома не моги...');
INSERT INTO `locales_item` VALUES (19254, 'Sayge\'s Fortune #21', '세이지의 점괘 #21', 'Prédiction de Sayge n°21', 'Sayges Horoskop Nr. 21', '塞格的塔罗牌#21', '賽吉的占卜#21', 'Fortuna de Sayge n.º 21', 'Fortuna de Sayge n.º 21', 'Предсказание Воржея #21', 'Divine Shields and Hearthstones do not make a hero heroic.', '천상의 보호막과 귀환석은 영웅답지 못한 행동이니라.', 'Les boucliers divins et les pierres de foyer ne rendent pas un héros héroïque.', '', '神圣之盾和炉石并不是英雄所必备的。', '神聖之盾和爐石並不是英雄所必備的。', 'Los escudos divinos y las piedras de hogar no hacen a un héroe heroico.', 'Los escudos divinos y las piedras de hogar no hacen a un héroe heroico.', 'Священных щитов и камней возвращения мало, чтобы стать героем.');
INSERT INTO `locales_item` VALUES (19255, 'Sayge\'s Fortune #22', '세이지의 점괘 #22', 'Prédiction de Sayge n°22', 'Sayges Horoskop Nr. 22', '塞格的塔罗牌#22', '賽吉的占卜#22', 'Fortuna de Sayge n.º 22', 'Fortuna de Sayge n.º 22', 'Предсказание Воржея #22', 'An answer in blue is always true.', '파란색 답이 늘 정답이니라.', 'Une réponse en bleu est toujours vraie.', '', '蓝色的回答总是正确的。', '藍色的回答總是正確的。', 'Una respuesta en azul siempre es verdadera.', 'Una respuesta en azul siempre es verdadera.', 'Синий ответ – правды завет.');
INSERT INTO `locales_item` VALUES (19256, 'Sayge\'s Fortune #2', '세이지의 점괘 #2', 'Prédiction de Sayge n°2', 'Sayges Horoskop Nr. 2', '塞格的塔罗牌#2', '賽吉的占卜#2', 'Fortuna de Sayge n.º 2', 'Fortuna de Sayge n.º 2', 'Предсказание Воржея #2', 'You will find something wonderful tomorrow.', '내일, 놀라운 무언가를 발견하게 되리라.', 'Vous trouverez quelque chose de merveilleux, demain.', '', '你明天将会有新的惊喜。', '你明天將會有新的驚喜。', 'Mañana hallarás algo fabuloso.', 'Mañana hallarás algo fabuloso.', 'Завтра тебя ждет прекрасная находка.');
