INSERT INTO `locales_item` VALUES (19423, 'Sayge\'s Fortune #23', '세이지의 점괘 #23', 'Prédiction de Sayge n°23', 'Sayges Horoskop Nr. 23', '塞格的塔罗牌#23', '賽吉的占卜#23', 'Fortuna de Sayge n.º 23', 'Fortuna de Sayge n.º 23', 'Предсказание Воржея #23', 'Your fortune awaits you in Eastvale.', '동쪽계곡으로 가서 당신의 행운을 맞이하라.', 'Une surprise vous attend au Val d\'est.', '', '你的财富在东谷等着你。', '你的財富在東谷等著你。', 'La fortuna te aguarda en la Vega del Este.', 'La fortuna te aguarda en la Vega del Este.', 'В Восточной Долине тебя ждет удача.');
INSERT INTO `locales_item` VALUES (19424, 'Sayge\'s Fortune #24', '세이지의 점괘 #24', 'Prédiction de Sayge n°24', 'Sayges Horoskop Nr. 24', '塞格的塔罗牌#24', '賽吉的占卜#24', 'Fortuna de Sayge n.º 24', 'Fortuna de Sayge n.º 24', 'Предсказание Воржея #24', 'Your fortune awaits you inside the Deadmines.', '새로운 사랑과 함께 행복을 누리리라.', 'Une surprise vous attend au fond des Mortemines.', '', '你的财富在死亡矿井中等着你。', '你會在新的戀情中找到幸福。', 'Encontrarás la felicidad con un nuevo amor.', 'Encontrarás la felicidad con un nuevo amor.', 'В Мертвых копях тебя ждет удача!');
