INSERT INTO `locales_item` VALUES (19451, 'Sayge\'s Fortune #26', '세이지의 점괘 #26', 'Prédiction de Sayge n°26', 'Sayges Horoskop Nr. 26', '塞格的塔罗牌#26', '賽吉的占卜#26', 'Fortuna de Sayge n.º 26', 'Fortuna de Sayge n.º 26', 'Предсказание Воржея #26', 'Time is nothing; timing is everything.', '시간에 얽매이지 말라. 중요한 것은 때를 맞추는 일이니라.', 'Le temps n\'est rien ; le temps est tout.', '', '时间一文不值，把握时间才是一切。', '時間一文不值，把握時間才是一切。', 'El tiempo no es nada; el tiempo lo es todo.', 'El tiempo no es nada; el tiempo lo es todo.', 'Время – ничто, своевременность – все!');
