INSERT INTO `locales_item` VALUES (50019, 'Moonkin Hatchling', '', '', '', '枭兽宝宝', '', '', '', '', 'Moonkins are blessed by Elune and spread nature\'s grace wherever they travel. The festive fowls are always in the mood for a dance.', NULL, NULL, NULL, '月光精灵收到艾露恩女神的祝福，传播自然的恩典。无论走到哪里，这些喜庆的生灵们总是热衷于跳舞。', NULL, NULL, NULL, NULL);
