INSERT INTO `locales_item` VALUES (50056, 'City Protector\'s Medallion', '', '', '', '城市保卫者勋章', '', '', '', '', 'Sends you to your capital city. You must become a City Protector to use this item.', NULL, NULL, NULL, '将你传送到首都。你必须成为城市保卫者才能使用这件物品。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50058, 'Black Piglet', '', '', '', '黑色小猪', '', '', '', '', 'An easy-going traveling companion.', NULL, NULL, NULL, '一个随和的旅行伙伴。', NULL, NULL, NULL, NULL);
