INSERT INTO `locales_item` VALUES (50065, 'Anatomy Class Notes', '', '', '', '解剖学课堂笔记', '', '', '', '', '', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50066, 'Steel Mechanostrider', '', '', '', '铁甲机械陆行鸟', '', '', '', '', 'A mechanical marvel, built to withstand the toughest of battles.', NULL, NULL, NULL, '一个机械中的奇迹，为了抵御最艰苦的战斗而建造', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50067, 'Albino Snake', '', '', '', '白化蛇', '', '', '', '', 'A favored companion of Kirin Tor magi, this reptile makes one wonder whether it\'s truly a snake or something else altogether.', NULL, NULL, NULL, '这种爬虫动物是肯瑞托法师们所喜爱的伙伴,它让人不敢相信这真的是一条蛇,而是另外一种生物。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50068, 'Green Water Snake', '', '', '', '绿色水蛇', '', '', '', '', 'Brought to Sparkwater Port aboard merchant ships, these short-lived reptiles are considered pests by the port\'s residents.', NULL, NULL, NULL, '这种短命的爬虫通过商船被带到了火花水港，港口的居民都认为它们是害虫。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50069, 'Scarlet Snake', '', '', '', '猩红色毒蛇', '', '', '', '', 'Brave assassins sometimes capture these critters to use their highly toxic venom to poison weapons.', NULL, NULL, NULL, '勇敢的刺客有时候会捕捉这种毒蛇，将它们的剧毒毒液涂抹在自己的武器之上。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50070, 'Bronze Whelpling', '', '', '', '青铜幼龙', '', '', '', '', 'The Bronze Whelpling was lost in time until an unusual event allowed her to escape.', NULL, NULL, NULL, '这只青铜幼龙在时间中迷失了，直到一次偶然她才从时间漩涡中逃脱。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50071, 'Ivory Tallstrider', '', '', '', '象牙陆行鸟', '', '', '', '', '', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50072, 'Brown Tallstrider', '', '', '', '棕色陆行鸟', '', '', '', '', '', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50073, 'Gray Tallstrider', '', '', '', '灰色陆行鸟', '', '', '', '', 'A stoic and observant creature, adapting to any environment it encounters.', NULL, NULL, NULL, '这是一种沉着冷静且善于观察的生物，能适应任何环境', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50074, 'Pink talstrider', '', '', '', '粉色陆行鸟', '', '', '', '', 'A vibrant and playful bird, spreading joy wherever it goes.', NULL, NULL, NULL, '一种色彩鲜艳的鸟，无论走到哪都能传播欢乐', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50075, 'Purple Tallstrider', '', '', '', '紫色长脚鸟', '', '', '', '', 'Accidentally released by the Darkmoon Faire — makes for a surprisingly sturdy steed.', NULL, NULL, NULL, '这原本是暗月马戏团不小心放生出来的，然而作为坐骑却出人意料的强壮和结实', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50076, 'Turquoise Tallstrider', '', '', '', '绿松石陆行鸟', '', '', '', '', 'A rare and exotic bird, with feathers as bright as the tropical seas.', NULL, NULL, NULL, '一种稀有的异域鸟类，它的羽毛明亮夺目。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50077, 'Brightwing', '', '', '', '布莱特文', '', '', '', '', 'Hello, friend! Brightwing likes it when you visit!', NULL, NULL, NULL, '你好朋友，布拉特文欢迎您的拜访', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50078, 'Dart Frog', '', '', '', '飞箭蛙', '', '', '', '', 'Toads and frogs are fast friends of trolls, perfect for poisons.', NULL, NULL, NULL, '蟾蜍和青蛙都与巨魔关系密切，因为它们与制作毒药完美契合。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50079, 'Island Frog', '', '', '', '岛屿蛙', '', '', '', '', 'This little friend snuck into your boot to join you on your travels.', NULL, NULL, NULL, '这个小伙伴偷偷爬进了你的鞋子里，想加入你的旅行。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50080, 'Eagle Owl', '', '', '', '鹰头猫头鹰', '', '', '', '', 'Many owls nest high in the stone structures of Darnassus, hunting any pests that enter the night elves\' city.', NULL, NULL, NULL, '许多猫头鹰的巢穴在达纳苏斯的建筑结构上，猎杀任何胆敢进犯暗夜精灵城市的敌人。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50081, 'Cottontail Rabbit', '', '', '', '小尾兔', '', '', '', '', 'Mountain cottontails can leap up a steep incline with speed you would not believe.', NULL, NULL, NULL, '山中的小尾兔可以以惊人的速度爬上陡峭的斜坡。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50082, 'Snowy Owl', '', '', '', '雪枭', '', '', '', '', 'Winterspring\'s furbolg prize the brilliant white feathers of these majestic creatures for ritual purposes.', NULL, NULL, NULL, '冬泉谷的熊怪们很看重这种生物夺目的白色羽毛，会将羽毛用于某些仪式之中。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50083, 'Azure Whelpling', '', '', '', '蓝龙雏龙', '', '', '', '', 'Like other members of the blue dragonflight, these whimsical little critters display an affinity to arcane magic.', NULL, NULL, NULL, '和蓝龙军团的其他成员一样，这些古怪的小家伙们表现出和奥术魔法的亲和力。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50084, 'Kirin Tor Familiar', '', '', '', '肯瑞托魔仆', '', '', '', '', 'Who knew he was so into books?', NULL, NULL, NULL, '有谁懂它为什么这么喜欢看书。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50085, 'Frostwolf Ghostpup', '', '', '', '霜狼幽灵幼崽', '', '', '', '', 'The little wolf told to stay. Watching, waiting, for vacant prey. Too proud to leave, she slipped away. Unburdened now, forever free to play.', NULL, NULL, NULL, '小狼曾被告知要留下，看守猎物等待大狼们回家，她却自豪地不愿留下，战斗激发，她定格在这个盛夏，现在的她,能永远无拘无束地玩耍.', NULL, NULL, NULL, NULL);
