INSERT INTO `locales_item` VALUES (50236, 'Stormborn\'s Cape', '', '', '', '风暴之子斗篷', '', '', '', '', 'We shall not pretend to any understanding of the bond between dragon and dragonrider; wiser heads have pondered that mystery for centuries. We do know however, that dragons are not horses, to be ridden by any man who throws a saddle on their back.', NULL, NULL, NULL, '我们不应该对龙与龙骑士之间的羁绊指手画脚，因为智者们已经探寻这个奥秘百余年。然而我们知道，龙不是马，不是随便套上鞍就可以骑的。', NULL, NULL, NULL, NULL);
