INSERT INTO `locales_item` VALUES (50399, 'Ancient Quel\'dorei Steed', '', '', '', '上古奎尔多雷战马', '', '', '', '', 'Comes from a lineage of fine horses that once grazed near the shores of the Well of Eternity.', NULL, NULL, NULL, '这种马曾经生活在永恒之井周围，拥有优良的血统。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50400, 'Riding Zhevra', '', '', '', '骑乘斑纹斑马', '', '', '', '', 'Zhevras are rarely used as mounts in Azeroth due to their stubborn nature and tendency to bite.', NULL, NULL, NULL, '因为难以驯服，斑马很少被用于骑乘。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50401, 'Armored Ivory Raptor', '', '', '', '装甲象牙迅猛龙', '', '', '', '', 'Longtime allies of the trolls, these jungle hunters form a special bond with their masters. They become steed, guardian, and friend.', NULL, NULL, NULL, '他们长期以来都是巨魔的伙伴，这些丛林猎人与它们的主人形成了特殊的羁绊。它们成为了主人的坐骑、护卫与朋友。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50402, 'Armored Violet Raptor', '', '', '', '装甲紫罗兰迅猛龙', '', '', '', '', 'Longtime allies of the trolls, these jungle hunters form a special bond with their masters. They become steed, guardian, and friend.', NULL, NULL, NULL, '他们长期以来都是巨魔的伙伴，这些丛林猎人与它们的主人形成了特殊的羁绊。它们成为了主人的坐骑、护卫与朋友。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50403, 'Armored Red Raptor', '', '', '', '装甲红色迅猛龙', '', '', '', '', 'Longtime allies of the trolls, these jungle hunters form a special bond with their masters. They become steed, guardian, and friend.', NULL, NULL, NULL, '他们长期以来都是巨魔的伙伴，这些丛林猎人与它们的主人形成了特殊的羁绊。它们成为了主人的坐骑、护卫与朋友。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50404, 'Armored Obsidian Raptor', '', '', '', '装甲黑曜石迅猛龙', '', '', '', '', 'Longtime allies of the trolls, these jungle hunters form a special bond with their masters. They become steed, guardian, and friend.', NULL, NULL, NULL, '他们长期以来都是巨魔的伙伴，这些丛林猎人与它们的主人形成了特殊的羁绊。它们成为了主人的坐骑、护卫与朋友。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50405, 'Spectral Gryphon Essence', '', '', '', '幽灵狮鹫精华', '', '', '', '', '', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50406, 'Shadowhorn Stag', '', '', '', '暗角雄鹿', '', '', '', '', 'A powerful, beautiful being.', NULL, NULL, NULL, '一种充满力量的优雅生物。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50407, 'Nightmare Dreamrunner', '', '', '', '噩梦行者', '', '', '', '', 'A nightmarish steed of hardened steel and vengeful spirits, this companion will follow you to the depths of the Molten Core and back without complaint.', NULL, NULL, NULL, '一个由怨灵和钢铁组成的坐骑，它非常忠诚、毫无怨言，随便是随你进入熔火之心最深处也无怨无悔。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (50408, 'Illusion: Dryad', '', '', '', '幻化：树妖', '', '', '', '', 'This disguise will work until logout.', NULL, NULL, NULL, '这个伪装会持续到退出游戏', NULL, NULL, NULL, NULL);
