INSERT INTO `locales_item` VALUES (50536, 'Twilight', '', '', '', '地狱之影', '', '', '', '', 'A mount that embodies the perfect balance between darkness and beauty.', NULL, NULL, NULL, '感受骑着地狱之影上的快感吧，它是黑暗与美丽之间的完美平衡。', NULL, NULL, NULL, NULL);
