INSERT INTO `locales_item` VALUES (50601, 'Summon: Surgeon', '', '', '', '召唤：外科医生', '', '', '', '', 'Summon Dr. Topnose, your own private surgeon. List of services include scar removal, broken nose fix and others.', NULL, NULL, NULL, '召唤你的私人外科医生，他提供疤痕祛除、鼻梁修复等服务。', NULL, NULL, NULL, NULL);
