INSERT INTO `locales_item` VALUES (51600, 'Ancient Spell Locket', '', '', '', '上古符咒挂饰', '', '', '', '', 'An old spell is still emanating with arcane runes and the incantation is too worn to read properly.', NULL, NULL, NULL, '一个被奥术符文缠绕的古老符咒，符咒有所破损，所以我们无法理解其中的奥秘。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51601, 'Othmar Garithos\' Coin', '', '', '', '奥瑟莫·加利苏斯的硬币', '', '', '', '', 'Keep your wishes for yourself. I do not negotiate with fountains.', NULL, NULL, NULL, '自己把握自己的愿望。我不和喷泉谈判。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51602, 'Nathanos Marris\' Coin', '', '', '', '纳萨诺斯·玛瑞斯的硬币', '', '', '', '', 'Only her belief in my skills allowed it, not any Halduron or Renthar with that whimsical Lor\'themar. Only her.', NULL, NULL, NULL, '只有她对我的信任才会允许我这么做。不论是谁都不允许我这么做，但只有她会允许。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51603, 'Arthas\' Gold Coin', '', '', '', '阿尔萨斯的金币', '', '', '', '', 'Already, I\'ve a kingdom in my prospects, a land to rule. What to ask for? Perhaps a frozen scone...', NULL, NULL, NULL, '我已经是一个王国的储君了，将要治理这片疆土，还能许什么愿望呢？不如来个凉快点的王座吧......', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51604, 'Speedy\'s Gold Coin', '', '', '', '史毕迪的金币', '', '', '', '', 'Be sure to bring your friends over.', NULL, NULL, NULL, '记得一定要带你的朋友来哦！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51605, 'Vaedath\'s Silver Coin', '', '', '', '维达斯的银币', '', '', '', '', 'Now the entire raid can use my hole!', NULL, NULL, NULL, '现在整个团队都在用我创造的洞了。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51606, 'Felicia\'s Silver Coin', '', '', '', '菲利希亚的银币', '', '', '', '', 'Style is a way to say who you are without having to speak. ', NULL, NULL, NULL, '风格就是不说话就能让别人知道你是谁的方式。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51607, 'Sinrek\'s Silver Coin', '', '', '', '辛雷克的银币', '', '', '', '', 'Live and let live or die trying.', NULL, NULL, NULL, '要么活，要么让别人活，要么死在活的道路之上。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51608, 'King Mrgl-Mrgl\'s Coin', '', '', '', '国王姆嘎姆嘎的硬币', '', '', '', '', 'Some days, I think the murlocs don\'t appreciate everything I do for them.', NULL, NULL, NULL, '有时候，我觉得海豚们并不感谢我为他们所做的一切。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51609, 'Barthilas\' Copper Coin', '', '', '', '巴瑟拉斯的铜币', '', '', '', '', 'I wish … I wish Patricia would always be near me!', NULL, NULL, NULL, '我希望...我希望帕特丽夏能永远呆在我的身边。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51610, 'Murky\'s Coin', '', '', '', '奔波儿霸的硬币', '', '', '', '', 'Mrr glrrrgl mrr glrrgl glrr.', NULL, NULL, NULL, '哇啦咕噜哇啦咕咕咕啦啦。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51611, 'Eitrigg\'s Copper Coin', '', '', '', '伊崔格的铜币', '', '', '', '', 'Whatever comes, the Horde will endure. It must!', NULL, NULL, NULL, '不论什么敌人来犯，部落都将永远坚持下去！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51612, 'A Peasant\'s Silver Coin', '', '', '', '农夫的银币', '', '', '', '', 'I\'m so forgetful! I wish I had a better memory. Wait, didn\'t I already throw a coin into here?', NULL, NULL, NULL, '我真健忘！我要是记性好一点就好了。等等，我是不是已经扔了一枚硬币进去？', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51613, 'Kryll\'s Copper Coin', '', '', '', '克里尔的铜币', '', '', '', '', 'Boom. Now boom? I wish for a boom. Boom go! This coin must be broken, I wonder if it\'ll explode.', NULL, NULL, NULL, '爆炸。现在就爆炸。快爆炸！这硬币肯定有问题，它到底能不能爆炸。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51614, 'Medivh\'s Silver Coin', '', '', '', '麦迪文的银币', '', '', '', '', 'I know how it will all end… I only wish I knew how to lessen the burden.', NULL, NULL, NULL, '我知道这一切终将结束，但我想知道如何拭去重负。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51615, 'Muradin Bronzebeard\'s Silver Coin', '', '', '', '穆拉丁·铜须的银币', '', '', '', '', 'May the Holy Light protect us on our expedition to the frozen north.', NULL, NULL, NULL, '愿圣光保佑我们这支诺森德远征队。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51616, 'Fandral Staghelm\'s Silver Coin', '', '', '', '范达尔·鹿盔的银币', '', '', '', '', 'The War of the Shifting Sands... I wish I could forget it ever happened.', NULL, NULL, NULL, '流沙之战......希望我能彻底忘掉它吧。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51617, 'Tyrande\'s Coin', '', '', '', '泰兰德的硬币', '', '', '', '', 'That I might protect those I hold dear, and continue to reflect the grace and light of Elune.', NULL, NULL, NULL, '我将保护我所爱之人，并继续传播艾露恩的优雅与圣洁。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51618, 'Malfurion\'s Coin', '', '', '', '玛法里奥的硬币', '', '', '', '', 'Were we too late to stop the Nightmare?', NULL, NULL, NULL, '我们是否已经来不及阻止梦魇的降临。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51619, 'Uther Lightbringer\'s Gold Coin', '', '', '', '乌瑟尔·光明使者的金币', '', '', '', '', 'Young Arthas must learn patience to temper his power. I will pray that he one day learns how to lead with care rather than force.', NULL, NULL, NULL, '年轻的阿尔萨斯必须学会耐心控制自己的力量。我祈祷他能了解到领袖的真谛在于品德，而非蛮力。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51620, 'Anduin Wrynn\'s Gold Coin', '', '', '', '安度因·乌瑞恩的金币', '', '', '', '', 'I wish I would grow up, it feels like I\'ve been 10 for years.', NULL, NULL, NULL, '我希望我能快点长大。好像我一直都是10岁的样子。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51621, 'Tirion Fordring\'s Gold Coin', '', '', '', '提里奥·弗丁的金币', '', '', '', '', 'It is my wish that my dear Taelan will grow strong enough to defend the people he cares for.', NULL, NULL, NULL, '我希望泰兰德能够茁壮成长，保卫她所在意的人们。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51622, 'Alonsus Faol\'s Copper Coin', '', '', '', '阿隆索斯·法奥的铜币', '', '', '', '', 'One day, I hope to spread the path of the Light to the common people and teach them the value of the Three Virtues.', NULL, NULL, NULL, '我希望有一天能够向芸芸众生宣讲圣光之道，教他们学会理解三大美德的价值。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51623, 'Antonidas\' Silver Coin', '', '', '', '安东尼达斯的银币', '', '', '', '', 'Grant me the strength to accept the things that I cannot change, the courage to change the things I can and the wisdom to know the difference.', NULL, NULL, NULL, '给我力量接受那些我无法改变之事，给我勇气改变那些我可以改变之事，给我智慧看清这两者之间的差别。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51624, 'Lady Katrana Prestor\'s Gold Coin', '', '', '', '卡特拉娜·普瑞斯托', '', '', '', '', 'Listen, little wishing fountain. You\'ll give me all your power if you know what\'s good for you.', NULL, NULL, NULL, '听着，小小的许愿池。把你的全部力量都给我，不然有你好看。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51625, 'Princess Calia Menethil\'s Copper Coin', '', '', '', '佳莉娅·米奈希尔公主的铜币', '', '', '', '', 'I hope that handsome nobleman Lord Prestor notices me! He\'s so dreamy!', NULL, NULL, NULL, '我希望那个英俊的贵族，普瑞斯托大人，能够注意到我！他真的太帅了！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51626, 'Private Marcus Jonathan\'s Copper Coin', '', '', '', '列兵马库斯·乔纳森的铜币', '', '', '', '', 'I wish to grow a glorious, bushy mustache someday.', NULL, NULL, NULL, '我希望能长出漂亮而浓密的胡须。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51627, 'Er\'s Coin', '', '', '', '厄尔的硬币', '', '', '', '', 'Penus.', NULL, NULL, NULL, '勾八。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51628, 'Torta\'s Gold Coin', '', '', '', '托塔的金币', '', '', '', '', 'If the left continent is broken, play on the right one.', NULL, NULL, NULL, '如果左边的大陆崩溃了，那就在右边踢球咯。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51629, 'Aurelian\'s Silver Coin', '', '', '', '奥雷利安的银币', '', '', '', '', 'By the power of the Lich… err, Light, burn!', NULL, NULL, NULL, '以巫妖的力量--啊！光！燃烧吧！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51630, 'Gifted\'s Silver Coin', '', '', '', '吉夫特的银币', '', '', '', '', 'I wish a certain paladin would learn how to heal finally…', NULL, NULL, NULL, '我希望某个圣骑士能学会怎么当个好治疗。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51631, 'Smultron\'s Silver Coin', '', '', '', '斯姆特隆的银币', '', '', '', '', 'I\'m rockin\'.', NULL, NULL, NULL, '我正在摇滚中。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51632, 'Momo\'s Silver Coin', '', '', '', '莫莫的银币', '', '', '', '', 'Frostbolt it!', NULL, NULL, NULL, '寒冰箭！BIU!BIU!', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51633, 'Chlo\'s Silver Coin', '', '', '', '克洛伊的银币', '', '', '', '', 'Can we prioritize healing of Chomper?', NULL, NULL, NULL, '我们能不能先治疗大嘴花？', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51634, 'Marta\'s Silver Coin', '', '', '', '玛塔的银币', '', '', '', '', 'RUSH B!', NULL, NULL, NULL, '冲B!', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51635, 'Pompa\'s Rubber Duck', '', '', '', '蓬帕的橡皮鸭', '', '', '', '', 'Quack!', NULL, NULL, NULL, '庸医！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51636, 'Chomper\'s Lost Tooth', '', '', '', '大嘴花丢掉的牙齿', '', '', '', '', 'That\'s big.', NULL, NULL, NULL, '好大啊。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51637, 'Inflatable Thunderfury, Blessed Blade of the Windseeker', '', '', '', '充气的逐风者祝福之剑', '', '', '', '', 'Deflated.', NULL, NULL, NULL, '把气门拔了。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51638, 'King Llane\'s Silver Coin', '', '', '', '莱恩国王的银币', '', '', '', '', 'I\'m sure we\'ll see the best of the outcome and laugh together at the end of this nuisance, Garona. Mark my words!', NULL, NULL, NULL, '我确信我们会看到最好的结果，并在一切繁琐事件解决时一起欢声笑语，迦罗娜。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51639, 'Smultron\'s Shades', '', '', '', '斯姆特隆的墨镜', '', '', '', '', 'I wear my goggles at night!', NULL, NULL, NULL, '我晚上都得戴着它。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51640, 'Engie\'s Coin', '', '', '', '恩吉的硬币', '', '', '', '', 'Fear in five!', NULL, NULL, NULL, '我怕五！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51641, 'Momo\'s Coin', '', '', '', '莫莫的硬币', '', '', '', '', 'WATCH OUT WATCH OUT WATCH OUT!', NULL, NULL, NULL, '小心小心小心！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51642, 'Herczeg\'s Silver Coin', '', '', '', '赫尔采格的银币', '', '', '', '', 'The Master of the Elements, The Emperor of the Storms and The Breaker of Sheeps, and the rest of the raid.', NULL, NULL, NULL, '元素领主，风暴之皇，羊之守护者和巴拉巴拉......', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51643, 'Marta\'s Silver Coin', '', '', '', '玛塔的银币', '', '', '', '', 'Kill all the Furbolgs.', NULL, NULL, NULL, '杀死所有熊怪！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51644, 'Kazgrim\'s Silver Coin', '', '', '', '卡兹格林的银币', '', '', '', '', 'I wish to be the true warchief.', NULL, NULL, NULL, '我希望能成为真正的大酋长。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51645, 'Dragunovi\'s Silver Coin', '', '', '', '德拉古诺夫的银币', '', '', '', '', 'You\'re probably wearing something I made.', NULL, NULL, NULL, '你可能穿着我做的衣服。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51646, 'Skadi\'s Gold Coin', '', '', '', '斯卡迪的金币', '', '', '', '', 'I wish to look back on those silent nights in the Gurubashi Arena with my rats.', NULL, NULL, NULL, '我希望能回忆起和我的老鼠们在古拉巴什竞技场度过的那些宁静夜晚。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51660, 'Gheor\'s Silver Coin', '', '', '', '盖奥尔的银币', '', '', '', '', 'Still looking for a hot goth girlfriend.\"', NULL, NULL, NULL, '还在找一个性感的哥特系女友。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51700, 'Cracked Raptor Egg', '', '', '', '破裂的迅猛龙蛋', '', '', '', '', 'It\'s about to hatch! What could be inside?', NULL, NULL, NULL, '快要出来了！里面会是什么呢？', NULL, NULL, NULL, NULL);
