INSERT INTO `locales_item` VALUES (51705, 'Simple Wooden Planter', '', '', '', '简易的木制花盆', '', '', '', '', 'Specially handcrafted planter with fertile and watered soil.', NULL, NULL, NULL, '特别的手搓种植盆，让土壤肥沃并锁住水分。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51706, 'Country Pumpkin Seeds', '', '', '', '乡村南瓜种子', '', '', '', '', 'Can be planted in Simple Wooden Planter. Requires watering and fertilizing.', NULL, NULL, NULL, '可以用把他种到花盆里。需要浇水和施肥。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51707, 'Mountain Berry Bush Seeds', '', '', '', '山地灌木浆果种子', '', '', '', '', 'Colorful berries from Hinterlands region. Can be planted in Simple Wooden Planter. Requires watering and fertilizing.', NULL, NULL, NULL, '一种来自内陆的彩色浆果，可以种植在简易花盆里。需要浇水和施肥。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (51708, 'Striped Melon Seeds', '', '', '', '条纹瓜种子', '', '', '', '', 'The sweetest sort ever known! Can be planted in Simple Wooden Planter. Requires watering and fertilizing.', NULL, NULL, NULL, '有史以来最甜的品种，可以种植在简易花盆里，需要浇水和施肥。', NULL, NULL, NULL, NULL);
