INSERT INTO `locales_item` VALUES (67000, 'Lovely Pink Fox', '', '', '', '可爱的粉色狐狸', '', '', '', '', 'A shy creature, the pink fox will only make its presence known to those that have befriended it.', NULL, NULL, NULL, '粉红狐狸是一种害羞的动物，它只会让那些和它交过朋友的人知道它的存在。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (67001, 'Anniversary Gift (4 years online)', '', '', '', '周年礼物', '', '', '', '', 'It\'s Turtle WoW\'s 4th anniversary! Many thanks for being the best gaming community in the world!', NULL, NULL, NULL, '乌龟魔兽四周年了！非常感谢各位共同的努力使它成为世界上最好的游戏社区。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (69000, 'Gilnean Raven', '', '', '', '吉尔尼斯渡鸦', '', '', '', '', 'For generations, the ravens of Gilneas have served as a timeless symbol of regal authority, reminding all of the lasting influence of House Greymane, even in the darkest of nights.', NULL, NULL, NULL, '这种渡鸦的羽毛在月光下会散发出诡异的光芒，即便是在夜间也很容易发现它的存在。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (69001, 'Tiny Warp Stalker', '', '', '', '迷你虚空行者', '', '', '', '', 'Not only is it quick, it\'s loud too!', NULL, NULL, NULL, '不仅非得快，而且声音还很大。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (69002, 'Scotty', '', '', '', '斯科蒂', '', '', '', '', 'Unique and intelligent piece of genius engineering!', NULL, NULL, NULL, '独特而智能的天才工程作品！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (69003, 'Flipper', '', '', '', '菲利普', '', '', '', '', 'Notable for its wide eyes and sassy slide.', NULL, NULL, NULL, '它不仅眼睛大，还很时髦。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (69004, 'Pengu', '', '', '', '小潘', '', '', '', '', 'It\'s appearance evokes a more civilized era, when duelists battled in tuxedos.', NULL, NULL, NULL, '它的外观让人想起了一个更文明的时代，那时的决斗者在竞技场中战斗。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (69006, 'Glitterwing', '', '', '', '闪翼', '', '', '', '', 'These flying creatures do not leave feathers out in the wild. If a feather happens to ever detach from their body, the feather glows brilliantly for a moment and then vanishes from sight.', NULL, NULL, NULL, '这些会飞的生物不会在野外留下羽毛。因为如果有一根羽毛碰巧从它们身上掉落，那根羽毛会在空中发光，接着便从视线中消失了。', NULL, NULL, NULL, NULL);
