INSERT INTO `locales_item` VALUES (80000, 'Golden Dragonhawk Hatchling', '', '', '', '金色龙鹰宝宝', '', '', '', '', 'Once prized by dragonhawk breeders in Silvermoon. Stands out at night to predators, making it necessary to gain awareness at an early age.', NULL, NULL, NULL, '曾经被银月城的龙鹰饲养者所珍视。对于狩猎者来说，它们在夜间很显眼，因此从小便有了非常警觉的意识。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80001, 'Thalassian Tender', '', '', '', '奎尔萨拉斯酥肉卷', '', '', '', '', 'It always wakes up dancing. What a happy little tree!', NULL, NULL, NULL, '它总是伴随着舞蹈而醒来，多么快乐的小树啊！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80003, 'Black-Footed Fox', '', '', '', '黑足狐', '', '', '', '', 'During frigid nights, these critters use their fluffy tails as a blanket to stay warm.', NULL, NULL, NULL, '在寒冷的夜晚，这些小动物用它们毛绒绒的尾巴当毯子来取暖。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80004, 'Cheeky Monkey', '', '', '', '顽皮猴', '', '', '', '', 'With their mischievous nature and cute antics, these baby monkeys are the perfect companions to brighten up your adventures in Azeroth.', NULL, NULL, NULL, '艾泽拉斯的猴子们是臭名昭著的骗子，而这些深受暗月马戏团爱戴的同伴们将狡猾提高到了一个全新的境界。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80006, 'Arcane Elemental', '', '', '', '奥术元素', '', '', '', '', 'In case of darkness, this little elemental is an infinite source of a soothing blue glow.', NULL, NULL, NULL, '在黑暗之中，这些小元素是一种无限的舒缓蓝色光源。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80007, 'Enchanted Broom', '', '', '', '魔法扫帚', '', '', '', '', 'Created by a high elf apprentice, this broom would be extremely useful if anyone could figure out how to make it stop.', NULL, NULL, NULL, '这把扫帚是一个高等精灵魔法学徒创造的，如果有人能想出如何让它停下来的话，那它会是一个非常有用的伙伴。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80008, 'Temporal Bronze Disc', '', '', '', '时光铜盘', '', '', '', '', 'Given to you by Chromie to close time rifts around the timeways, but where does the energy go?', NULL, NULL, NULL, '克罗米送给你的，用来关闭时间之流上的时间裂痕，但是它的能量去哪了。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80010, 'Midnight', '', '', '', '午夜', '', '', '', '', 'Ride with the moon (and this furry, whiskered witch) in the dead of night!', NULL, NULL, NULL, '在夜深人静的时候，和月亮（还有毛茸茸、长着胡须的女巫）一起骑行吧！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80060, 'Glyph of War', '', '', '', '战争模式', '', '', '', '', 'You can no longer disable PvP mode but experience gain from all sources is increased. Effect persists after reaching level 60.', NULL, NULL, NULL, '你不能再禁用PVP模式，但是所有经验都会获得增益。达到60级后效果将持续。', NULL, NULL, NULL, NULL);
