INSERT INTO `locales_item` VALUES (80180, 'Crown of the Damned', '', '', '', '诅咒之冠', '', '', '', '', 'Abandon all hope...', NULL, NULL, NULL, '放弃一切希望......', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80181, 'Bulwark of the Damned', '', '', '', '诅咒壁甲', '', '', '', '', 'Our fate cannot be taken from us...', NULL, NULL, NULL, '我们的命运不能被夺走.......', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80182, 'Sabatons of the Damned', '', '', '', '诅咒马靴', '', '', '', '', 'I am the way into eternal pain...', NULL, NULL, NULL, '我是通往永恒痛苦的道路......', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80183, 'Chausses of the Damned', '', '', '', '诅咒马裤', '', '', '', '', 'These dwell among the blackest souls...', NULL, NULL, NULL, '这些存在于最黑暗的灵魂之中......', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80184, 'Girdle of the Damned', '', '', '', '诅咒腰带', '', '', '', '', 'Let us descend now into the blind world...', NULL, NULL, NULL, '现在让我们进入这个无助的世界...', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80185, 'Grasps of the Damned', '', '', '', '诅咒手套', '', '', '', '', 'Here pity only lives when it is dead...', NULL, NULL, NULL, '在这里，怜悯只有在它快死去的时候才存在...', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80186, 'Epaulets of the Damned', '', '', '', '诅咒护肩', '', '', '', '', 'We were men once...', NULL, NULL, NULL, '我们也曾经是真正的男人...', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80187, 'Tabard of the Immortal Guardian', '', '', '', '不朽守护者战袍', '', '', '', '', 'How do you spot a hardcore player in a crowd? You don\'t have to, they\'ll make sure you know it.', NULL, NULL, NULL, '怎么在人群中找出一个硬汉？你不需要这么做，它们会确保你知道谁是。', NULL, NULL, NULL, NULL);
