INSERT INTO `locales_item` VALUES (80400, 'Quark\'s Shack Membership Card', '', '', '', '夸克小屋会员卡', '', '', '', '', 'Learn the customer\'s weaknesses so that you can better take advantage of him.', NULL, NULL, NULL, '了解顾客的弱点，这样你就能更好地利用他。', NULL, NULL, NULL, NULL);
