INSERT INTO `locales_item` VALUES (80410, 'High Elf Orphan Whistle', '', '', '', '高等精灵孤儿哨子', '', '', '', '', 'Summon and dismiss the orphan you\'ve agreed to look after.', NULL, NULL, NULL, '召唤和解散你答应照顾的孤儿。', NULL, NULL, NULL, NULL);
