INSERT INTO `locales_item` VALUES (80423, 'Zol\'majin\'s Voodoo Doll', '', '', '', '佐尔玛金的巫毒娃娃', '', '', '', '', 'The doll resembles Warleader Zol\'majin.', NULL, NULL, NULL, '娃娃看起来像佐尔玛金。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80425, 'White Stag', '', '', '', '白色雄鹿', '', '', '', '', 'A powerful, beautiful being.', NULL, NULL, NULL, '强大而优雅的生物。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80430, 'Armored Spectral Tiger', '', '', '', '装甲幽灵虎', '', '', '', '', 'Historians claim that these incorporeal beasts were created when Draenor exploded, unleashing energies that warped the world\'s flora and fauna.', NULL, NULL, NULL, '历史学家称，这些无形的野兽是德拉诺爆炸时创造的，爆炸释放的能量扭曲了动植物。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80431, 'Swift Magic Rooster', '', '', '', '迅捷魔法公鸡', '', '', '', '', 'Magic in the hands of a genius can do wonderful, miraculous things. Magic in the hands of an idiot can make a giant rooster.', NULL, NULL, NULL, '魔法在天才手中可以创造出奇妙、神奇的事物，而在白痴手中则创造出了一只公鸡。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80433, 'Black Bear', '', '', '', '黑熊', '', '', '', '', 'He\'s big, he\'s ready for battle, and he\'s a bear. What more could you want in a mount?', NULL, NULL, NULL, '它身材高大，随时准备战斗，而且还是一头熊。作为坐骑还能有什么要求呢？', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80438, 'Brown Bear', '', '', '', '棕熊', '', '', '', '', 'He\'s big, he\'s ready for battle, and he\'s a bear. What more could you want in a mount?', NULL, NULL, NULL, '它身材高大，随时准备战斗，而且还是一头熊。作为坐骑还能有什么要求呢？', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80443, 'Armored Brewfest Ram', '', '', '', '装甲美酒节公羊', '', '', '', '', 'Dwarves attribute this breed\'s even temperament to rigorous training, but other races argue that a daily diet of strong ale has something to do with it.', NULL, NULL, NULL, '矮人将这个品种的气质归结于严格的训练，但其他种族则认为这与每天饮用烈性麦芽酒有关。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80446, 'Armored Nightsaber', '', '', '', '装甲夜刃豹', '', '', '', '', 'When a night elf\'s mount perishes, it is custom for the rider to keep one of the saber\'s great fangs as a token of remembrance.', NULL, NULL, NULL, '当暗夜精灵的坐骑死亡时，按照习俗，骑手会保留一把军刀作为其往生的象征。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80447, 'Armored Horde Wolf', '', '', '', '装甲部落战狼', '', '', '', '', 'If asked to fetch, will most likely bring you back the head of a small mammal or humanoid.', NULL, NULL, NULL, '如果让它帮你取东西，它很可能会给你带回一个小型哺乳动物或者人形动物的头颅。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80449, 'Armored Alliance Steed', '', '', '', '装甲联盟战马', '', '', '', '', 'Armored to withstand collisions in battle.', NULL, NULL, NULL, '铠甲能够承受住战斗中的碰撞。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80455, 'Armored Brewfest Kodo', '', '', '', '装甲美酒节科多兽', '', '', '', '', 'Afestive mount, celebrating the joyous spirit of Brewfest.', NULL, NULL, NULL, '代表庆祝美酒节的欢乐精神。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80457, 'Armored Thalassian Unicorn', '', '', '', '装甲奎尔萨拉斯独角兽', '', '', '', '', 'A mythical creature, protected by enchanted armor, embodying grace and power.', NULL, NULL, NULL, '一种传说生物，受到魔法铠甲的保护，象征优雅和力量。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80458, 'Ornate Thalassian Unicorn', '', '', '', '精致的奎尔萨拉斯独角兽', '', '', '', '', 'A majestic mount, hailing from the enchanted forests of Quel\'Thalas.', NULL, NULL, NULL, '威风凛凛的坐骑，来自于奎尔萨拉斯的魔法森林。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80459, 'White Thalassian Unicorn', '', '', '', '白色奎尔萨拉斯独角兽', '', '', '', '', 'A rare and magical creature, sought after by those who appreciate beauty and elegance.', NULL, NULL, NULL, '一种罕见而神奇的生物，受那些欣赏美丽和优雅之人的追捧。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (80460, 'Red Rocket Car', '', '', '', '红色火箭车', '', '', '', '', 'Always go twenty over the speed limit.', NULL, NULL, NULL, '时速一直保持在20英里以上。', NULL, NULL, NULL, NULL);
