INSERT INTO `locales_item` VALUES (81100, 'Reins of the Raven Lord', '', '', '', '乌鸦领主的缰绳', '', '', '', '', 'The rest be forgotten to walk upon the ground, clipped wings and shame.', NULL, NULL, NULL, '其它的都已遗忘，只会在地面行走，夹着翅膀，充满羞耻。', NULL, NULL, NULL, NULL);
