INSERT INTO `locales_item` VALUES (81102, 'Darkmoon Dancing Bear', '', '', '', '欢乐缤纷云', '', '', '', '', 'These fearsome mounts have a habit of suddenly breaking out into dance amid battle, much to the annoyance of their riders.', NULL, NULL, NULL, '这些可怕的坐骑有一种习惯，会突然爆发战舞，这令骑手非常恼火。', NULL, NULL, NULL, NULL);
