INSERT INTO `locales_item` VALUES (81119, 'Plane Ticket', '', '', '', '飞机票', '', '', '', '', 'A one way ticket to the Shimmering Flats.', NULL, NULL, NULL, '一张去微光公寓的单程票。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81120, 'Frayfeather Hippogryph', '', '', '', '乱羽角鹰兽', '', '', '', '', 'Ancient mounts of the Highborne, they can rarely be found due to their latent magical powers.', NULL, NULL, NULL, '上古高地坐骑，由于其潜在的魔法力量，他们很少被发现。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81121, 'Cenarion Hippogryph', '', '', '', '塞纳里奥角鹰兽', '', '', '', '', 'Members of the Cenarion Circle have shared a long and prosperous partnership with their hippogryph allies. When conflict is unavoidable, the Cenarion War Hippogryph is called into service.', NULL, NULL, NULL, '塞纳里奥议会的成员和他们的鹰角兽盟友有着长期合作的伙伴关系。当战斗无法避免时，塞纳里奥角鹰便会被作为战斗机器启用。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81122, 'Bloodfallen Cloak', '', '', '', '染血斗篷', '', '', '', '', 'Stained with the blood of innocents.', NULL, NULL, NULL, '沾满了无辜者的鲜血', NULL, NULL, NULL, NULL);
