INSERT INTO `locales_item` VALUES (81124, 'Helmet of the Scarlet Avenger', '', '', '', '血色复仇者头盔', '', '', '', '', 'A blazing heart and a pile of heretics at your feet.', NULL, NULL, NULL, '一颗炽热的心脏和一堆异教徒将被你踩在脚下。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81125, 'Inquisitor\'s Orb', '', '', '', '审判者法球', '', '', '', '', '', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL);
