INSERT INTO `locales_item` VALUES (81140, 'Steamwheedle Limited Edition Wormhole', '', '', '', '热砂港限制版虫洞', '', '', '', '', 'Takes you to the Steamwheedle Beach Experience. Notice: Upon use, the user consents that The Steamwheedle Cartel is not responsible for device malfunctions.', NULL, NULL, NULL, '带你去热砂港海滩体验。注意：在使用时，热砂港商会不对设备故障负责。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81142, 'Qiraji Ceremonial Shirt', '', '', '', '其拉祭祀短袖衬衫', '', '', '', '', 'February 13, 2021 — The day the Old God C\'thun was vanquished by me (some other people were there too).', NULL, NULL, NULL, '2021年2月13日，古神克苏恩被我们推倒的日子（其它的一些人也在和我们竞争）。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81143, 'Plates of Uldum', '', '', '', '奥丹姆石板', '', '', '', '', 'Not much remains, but perhaps it could be repaired.', NULL, NULL, NULL, '残余的部分不多，但或许可以修复。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81145, 'Illusion: Pandaren', '', '', '', '幻象：熊猫人', '', '', '', '', 'This disguise will work until logout.', NULL, NULL, NULL, '这个伪装会持续到退出游戏', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81150, 'Phoenix Hatchling', '', '', '', '凤凰雏鸟', '', '', '', '', 'A child of phoenix god Al\'ar, the hatchling takes flight immediately after birth.', NULL, NULL, NULL, '凤凰神-奥的孩子，在他出生后便立刻学会了飞翔。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81151, 'Spectral Faeling', '', '', '', '幽灵飞蜥', '', '', '', '', 'This unique species of faerie dragon is not usually found on Azeroth.', NULL, NULL, NULL, '这种独特的精灵龙在艾泽拉斯并不常见。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81152, 'Tiny Pterodactyl', '', '', '', '微型翼龙', '', '', '', '', 'In older age, these little terrors eat everything they want to and are prey to almost no other species.', NULL, NULL, NULL, '在成熟的年岁时，这些恐怖的生物会吃任何他们想吃的东西，这也导致了周围物种的灭绝。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81153, 'Armored Purple Bear', '', '', '', '装甲紫色战熊', '', '', '', '', 'This ursine mount\'s swiftness is enhanced by its heavy armor.', NULL, NULL, NULL, '这只熊坐骑的迅捷被他们身上的护甲增强了。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81154, 'Armored Black Bear', '', '', '', '装甲黑色战熊', '', '', '', '', 'This ursine mount\'s swiftness is enhanced by its heavy armor.', NULL, NULL, NULL, '这只熊坐骑的迅捷被他们身上的护甲增强了。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81155, 'Armored Red Bear', '', '', '', '装甲红色战熊', '', '', '', '', 'This ursine mount\'s swiftness is enhanced by its heavy armor.', NULL, NULL, NULL, '这只熊坐骑的迅捷被他们身上的护甲增强了。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81156, 'Reins of the Armored Dragonhawk', '', '', '', '装甲龙鹰缰绳', '', '', '', '', 'Dragonhawks are among the deadliest known predators. They are able to spot prey from great distances, rush in, and rend with both talon and beak.', NULL, NULL, NULL, '龙鹰是已知最致命的掠食者之一。它们能在很远的地方发现猎物，然后俯冲，用爪子和喙撕裂猎物。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81158, 'Armored Frostmane Bear', '', '', '', '装甲霜鬃战熊', '', '', '', '', 'This ursine mount\'s swiftness is enhanced by its heavy armor.', NULL, NULL, NULL, '这只熊坐骑的迅捷被他们身上的护甲增强了。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81159, 'Tiny Shore Crab', '', '', '', '小型海滨蟹', '', '', '', '', 'These arthropods line many Azerothian shores and seek to fulfill their one true desire: to pinch.', NULL, NULL, NULL, '这些节肢动物分布在艾泽拉斯许多海岸上，它们只有一个欲望：夹人。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81160, 'Tome of Expertise: Bows', '', '', '', '专精：弓', '', '', '', '', '', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81167, 'Chieftain\'s Ceremonial Mantle', '', '', '', '酋长礼仪护肩', '', '', '', '', '', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81181, 'Crab Shell', '', '', '', '蟹壳', '', '', '', '', '', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81182, 'Armored Darkspear Raptor', '', '', '', '暗矛装甲迅猛龙', '', '', '', '', 'Speed, cunning, and ferocity are the things trolls and raptors admire about each other.', NULL, NULL, NULL, '速度、狡猾和凶猛是巨魔和迅猛龙互相羡慕之处。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81183, 'Sunscale Hatchling', '', '', '', '阳鳞雏蛇', '', '', '', '', 'The bright scales of this rare wind serpent soak up the sunlight to keep it warm, even in shade.', NULL, NULL, NULL, '这种罕见的风蛇拥有明亮的鳞片，鳞片能吸收阳光，即使在阴凉处也能保持警惕。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81185, 'Aerie Peak Gryphon', '', '', '', '鹰巢山角鹰', '', '', '', '', 'Gryphons\' keen eyesight allows them to see over vast distances and warn their riders of any dangers that lie ahead.', NULL, NULL, NULL, '角鹰敏锐的视力能够看得很远，并提醒骑手前方任何的风吹草动。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81186, 'Armored Aerie Peak Gryphon', '', '', '', '鹰巢山武装角鹰', '', '', '', '', 'This noble gryphon is as staunch a battle companion as any a member of the Alliance could ask for.', NULL, NULL, NULL, '这只高贵的角鹰是联盟成员所能要求的最坚定的战斗伙伴。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81187, 'Outline: Iron Lantern', '', '', '', '草图：铁灯笼', '', '', '', '', '', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81190, 'Red Shredder X-0524A', '', '', '', '红色拆解者X-0524A', '', '', '', '', 'Fueled by a desire to extract and exploit the natural wonders of Azeroth.', NULL, NULL, NULL, '被一种想要开采和利用艾泽拉斯自然环境的力量所驱使。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81191, 'Green Shredder X-0524B', '', '', '', '绿色拆解者X-0524B', '', '', '', '', 'The destructive nature of goblins is best characterized by their shredders.', NULL, NULL, NULL, '地精的毁灭性本能很好地体现在他们的机器上。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81192, 'Black Scrapforged Mechaspider', '', '', '', '黑色废料机械蜘蛛', '', '', '', '', 'Smoky, sparky, and loud.', NULL, NULL, NULL, '烟雾滚滚，闪闪发光，声音巨大。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81193, 'Blue Scrapforged Mechaspider', '', '', '', '蓝色废料机械蜘蛛', '', '', '', '', 'The check engine light is always on, it\'s when it goes off that you should be worried.', NULL, NULL, NULL, '引擎指示灯总是亮着，当它熄灭时，你才应该担心。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81194, 'Green Scrapforged Mechaspider', '', '', '', '绿色废料机械蜘蛛', '', '', '', '', 'This mechaspider specializes in drilling, clamping, and shooting at the same time. A typical gnome invention.', NULL, NULL, NULL, '这台机器擅长钻孔、夹东西、和射击同时进行。很典型的侏儒发明。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81195, 'Red Scrapforged Mechaspider', '', '', '', '红色废料机械蜘蛛', '', '', '', '', 'Four-legged machine of destruction, for your riding pleasure.', NULL, NULL, NULL, '四条腿的毁灭机器，供你骑乘之乐。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81196, 'Schematic: Goblin Radio', '', '', '', '设计图：地精收音机', '', '', '', '', '', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81198, 'Armored Thunder Bluff Kodo', '', '', '', '雷霆崖装甲科多兽', '', '', '', '', 'An alpha member of the herd, this kodo is a prime example of the mighty creatures which thunder through Mulgore.', NULL, NULL, NULL, '作为族群的一员，这只科多兽是响彻莫高雷的强大生物的典型代表。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81199, 'Ancestral War Totem', '', '', '', '先祖战争图腾', '', '', '', '', 'Carved by our forefathers.', NULL, NULL, NULL, '我们的先祖雕刻而成。', NULL, NULL, NULL, NULL);
