INSERT INTO `locales_item` VALUES (81206, 'Dark Ranger [High Elf]', '', '', '', '黑暗游侠 [高等精灵]', '', '', '', '', 'This token will alter your character\'s skin, while leaving the haircut, hair color, and facial features unchanged.', NULL, NULL, NULL, '这个物品将改变你角色的皮肤，但保留发型，头发颜色以及面部特征。', NULL, NULL, NULL, NULL);
