INSERT INTO `locales_item` VALUES (81224, 'Dalaran Warhorse (Removed)', '', '', '', '达拉然战马（已移除）', '', '', '', '', 'The powerful and unyielding white stallion.', NULL, NULL, NULL, '强壮不屈的白色骏马。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81225, 'Armored Stormwind Warhorse', '', '', '', '暴风城装甲战马', '', '', '', '', 'Trained to withstand brutal hand-to-hand combat in the fiercest battlefields.', NULL, NULL, NULL, '经过训练，能在最激烈的战场上承受最残酷的战斗考验。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81226, 'Armored Brown Bear', '', '', '', '装甲棕熊', '', '', '', '', 'The Amani trolls decorate these ferocious mounts in magic amulets and ceremonial masks as a way to venerate the bear god Nalorakk.', NULL, NULL, NULL, '阿曼尼巨魔用魔法护符和仪式面具来装饰这些凶猛的坐骑，以此来致敬巨熊之神纳洛拉克。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81227, 'Striped Dawnsaber', '', '', '', '虎纹黎明豹', '', '', '', '', 'Night elves once believed that seeing this light colored saber breed in the wild was an ill omen.', NULL, NULL, NULL, '暗夜精灵认为在野外碰到这些生物，是不详的预兆。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81228, 'Tauren Spirit Walker [Tauren]', '', '', '', '牛头人灵魂行者 [牛头人]', '', '', '', '', 'This token will alter your character\'s skin, while leaving the haircut, hair color, and facial features unchanged.', NULL, NULL, NULL, '这个物品将改变你角色的皮肤，但保留发型，头发颜色以及面部特征。', NULL, NULL, NULL, NULL);
