INSERT INTO `locales_item` VALUES (81230, 'Necromancer III [Gnome]', '', '', '', '死灵法师 III [侏儒]', '', '', '', '', 'This token will alter your character\'s skin, while leaving the haircut, hair color, and facial features unchanged.', NULL, NULL, NULL, '这个物品将改变你角色的皮肤，但保留发型，头发颜色以及面部特征。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81231, 'Tamed Rak\'Shiri', '', '', '', '驯服的拉克西里', '', '', '', '', 'Taming this savage breed requires patience, strength, and a large supply of fake mice and twine.', NULL, NULL, NULL, '驯服这个野兽需要耐心、力量和大量的绳索。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81232, 'Azure Frostsaber', '', '', '', '苍蓝霜刃豹', '', '', '', '', 'The lack of spots or stripes marks this beast as a descendant of the most ancient frostsaber line.', NULL, NULL, NULL, '没有斑点和条纹标志着这只野兽是最古老的霜刃族后代。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81233, 'Armored Ironforge Ram', '', '', '', '装甲铁炉堡公羊', '', '', '', '', 'Wildhammer Fact Checker claims that this specific breed was the first type of ram domesticated by the dwarves when they settled in Dun Morogh.', NULL, NULL, NULL, '蛮锤调查声称，这个特定的品种是爱人定居丹莫洛时所驯养的第一种山羊。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81234, 'Brewfest Ram', '', '', '', '美酒节公羊', '', '', '', '', 'Brewers retired this mount from active advertising service after complaints that the beasts were \"too temperamental\" to control in major cities.', NULL, NULL, NULL, '美酒节工作人员抱怨这些生物道“太喜怒无常”了，随后便将其中活动中撤出。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81235, 'Armored Vermilion Deathcharger', '', '', '', '装甲绯红死亡战马', '', '', '', '', 'Some horses merely adopt the dark. This horse was born in it.', NULL, NULL, NULL, '有些马只适应黑暗，而他便是从黑暗中诞生。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81236, 'Armored Grey Steed', '', '', '', '装甲灰骏马', '', '', '', '', 'A veteran of some of the toughest battles fought by the Alliance.', NULL, NULL, NULL, '参加过联盟一些坚苦战役的老兵。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81237, 'Chieftain\'s Kodo', '', '', '', '酋长科多兽', '', '', '', '', 'This Kodo with a Ceremonial Attire is usually reserved for Clan Chieftains, but after the Tauren joined the Horde, they have been made available to Champions of Thunderbluff.', NULL, NULL, NULL, '这些身穿礼仪服的科多兽通常是留给氏族酋长的，但在牛头人加入不落后，他们也被提供给了雷霆崖的勇士。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81238, 'Turbo-Charged Flying Machine', '', '', '', '涡轮增压飞行器', '', '', '', '', 'Only the most talented engineers have the courage and the mental stamina to create a flying machine that boasts stability and safety. Turbo-charging one is just crazy!', NULL, NULL, NULL, '只有最有才华的工程师才有勇气和毅力去创造一种以稳定和安全著称的飞行器。涡轮增压飞行器，真的太疯狂了！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81239, 'Happy Whimsyshire Cloud', '', '', '', '悲伤缤纷云', '', '', '', '', 'The fluffiest little cloud in Azeroth.', NULL, NULL, NULL, '艾泽拉斯最蓬松的小云。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81240, 'Sad Whimsyshire Cloud', '', '', '', '巨龟战熊', '', '', '', '', 'Now the sun is in the sky, and for no reason why, the sad cloud is crying itself away.', NULL, NULL, NULL, '现在太阳当空，那片悲伤的云朵哭着走了。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81241, 'Armored Orgrimmar Wolf', '', '', '', '奥格瑞玛装甲战狼', '', '', '', '', 'The wolves of the Horde are befriended, not domesticated.', NULL, NULL, NULL, '部落的狼是朋友和伙伴，而不是驯养而来的。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81242, 'Viridian Hippogryph', '', '', '', '翠绿角鹰兽', '', '', '', '', 'Ancient mounts of the Highborne, now left to run wild, they can rarely be found due to their latent magical powers.', NULL, NULL, NULL, '上古高地坐骑，由于其潜在的魔法力量，他们很少被发现。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81243, 'Beaky', '', '', '', '贝基', '', '', '', '', 'A gift from the Wildhammer dwarves to the heroes of the Alliance, these hatchlings are descendants of the same gryphons ridden by Falstad and his entourage into Grim Batol.', NULL, NULL, NULL, '蛮锤矮人送给联盟英雄的礼物，他们是弗斯塔德和他的随从们骑入格瑞玛巴托的角鹰的后代。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81244, 'Armored Ebon Deathcharger', '', '', '', '黑曜装甲死亡战马', '', '', '', '', 'Some horses merely adopt the dark. This horse was born in it.', NULL, NULL, NULL, '有些马只适应黑暗，而他便是从黑暗中诞生。', NULL, NULL, NULL, NULL);
