INSERT INTO `locales_item` VALUES (81248, 'Finn the Shark', '', '', '', '鲨鱼芬恩', '', '', '', '', 'Big and safe to have at your side if you want to discover the world underneath the sea.', NULL, NULL, NULL, '如果你想探索海底世界，有它在，又舒适又安全。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81250, 'Reinforced Black Pounder', '', '', '', '加固的黑色碾碎者', '', '', '', '', 'A fearsome war machine, built to withstand the harshest of battles.', NULL, NULL, NULL, '可怕的战争机器，能承受最残酷的战斗。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (81251, 'Reinforced Blue Pounder', '', '', '', '加固的蓝色碾碎者', '', '', '', '', 'A fearsome war machine, built to withstand the harshest of battles.', NULL, NULL, NULL, '可怕的战争机器，能承受最残酷的战斗。', NULL, NULL, NULL, NULL);
