INSERT INTO `locales_item` VALUES (83265, 'Demon Hunter\'s Blindfold', '', '', '', '恶魔猎手眼罩', '', '', '', '', 'To become sightless, is to see the demonic.', NULL, NULL, NULL, '失明便是为了看见恶魔。', NULL, NULL, NULL, NULL);
