INSERT INTO `locales_item` VALUES (83270, 'Anniversary Gift (3 years online)', '', '', '', '周年纪念礼物', '', '', '', '', 'It\'s Turtle WoW\'s 3rd anniversary! Many thanks for being the best gaming community in the world!', NULL, NULL, NULL, '乌龟魔兽三周年了！非常感谢你们的贡献，使得我们成为世界上最好的魔兽社区！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (83271, 'Delicious Birthday Cake', '', '', '', '美味生日蛋糕', '', '', '', '', 'Happy Birthday, Turtle WoW!', NULL, NULL, NULL, '生日快乐，乌龟魔兽！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (83272, 'Mr. Tails', '', '', '', '尾巴先生', '', '', '', '', 'Save up on acorns along the way and share some undivided attention & love with Mr.Tails and he\'ll be the best companion on your long journey through Azeroth.', NULL, NULL, NULL, '在旅途中节省橡果，向尾巴先生分享一些关注和爱。它是你穿越艾泽拉斯的长途旅途中最好的伙伴。', NULL, NULL, NULL, NULL);
