INSERT INTO `locales_item` VALUES (83300, 'Lil\' K.T.', '', '', '', '小克', '', '', '', '', 'In life, Kel\'Thuzad betrayed the Kirin Tor and created the Cult of the Damned. In death, he serves the Scourge as the Archlich Lord of Naxxramas.', NULL, NULL, NULL, '生时，克尔苏加德背叛了肯瑞托，创建了诅咒教会。死后，他以纳克萨玛斯大巫妖的身份为天灾军团服务。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (83301, 'Core Hound Pup', '', '', '', '熔火恶犬小宠物', '', '', '', '', 'Found in the Firelands and the Molten Core, core hounds can trace their lineage back to the alpha male, Magmadar.', NULL, NULL, NULL, '在燃烧平原和熔火之心中发现的恶犬，其血统可以追溯到玛格曼达。', NULL, NULL, NULL, NULL);
