INSERT INTO `locales_item` VALUES (92001, 'Tome of Teleportation: Theramore', '', '', '', '传送典籍：塞拉摩', '', '', '', '', 'A weathered tome, imbued with the arcane knowledge, grants mages the ability to swiftly journey to the city\'s shores.', NULL, NULL, NULL, '一本充满奥术知识的魔法书籍，赋予法师快速前往城市海岸的能力。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (92002, 'Tome of Portals: Theramore', '', '', '', '传送门典籍：塞拉摩', '', '', '', '', 'An enchanted compendium that empowers mages to create portals leading to the city of Theramore, fostering swift transportation for allies and friends.', NULL, NULL, NULL, '一本魔法纲要，使法师能够创造前往塞拉摩的传送门，为盟友和朋友提供快速便捷的交通方式。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (92003, 'Tome of Teleportation: Stonard', '', '', '', '传送典籍：斯通纳德', '', '', '', '', 'A weathered tome, imbued with the arcane knowledge, grants mages the ability to swiftly journey to the outpost of Stonard.', NULL, NULL, NULL, '一本充满奥术知识的书籍，使法师能够迅速地前往斯通纳德前哨营地。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (92004, 'Tome of Portals: Stonard', '', '', '', '传送门典籍：斯通纳德', '', '', '', '', 'Unleashing the arcane essence contained within, this tome enables mages to conjure portals that transport them and their companions to the stronghold of Stonard, deep within the Swamp of Sorrow.', NULL, NULL, NULL, '其中满是奥术的奥秘，这种奥秘能够使法师召唤出传送门，将他和他的伙伴宋传送到悲伤沼泽深处的斯通纳德营地。', NULL, NULL, NULL, NULL);
