INSERT INTO `locales_item` VALUES (1041, 'Ancient Black Wolf', '', '', '', '远古黑色巨狼', '', '', '', '', 'Once thought to be nearly extinct, this wolf can still occasionally be seen in the company of a few Horde veterans.', NULL, NULL, NULL, '这种狼曾经被认为几乎灭绝，但偶尔还会在少数部落老兵的陪伴下出现。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (1134, 'Gray Wolf', '', '', '', '灰狼', '', '', '', '', 'A fierce and loyal companion of the wilderness.', NULL, NULL, NULL, '它是荒野中凶猛而忠诚的伙伴。', NULL, NULL, NULL, NULL);
