INSERT INTO `locales_item` VALUES (8630, 'Stranglethorn Tiger', '', '', '', '荆棘谷的老虎', '', '', '', '', 'The wonderful thing about tigers is tigers are wonderful things!', NULL, NULL, NULL, '老虎的奇妙之处在于，老虎是一种奇妙的东西！', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (16339, 'Commander\'s Steed', '', '', '', '指挥官的战马', '', '', '', '', '', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (13323, 'Purple Mechanostrider', '', '', '', '紫色机械陆行鸟', '', '', '', '', 'A sleek and stylish machine, perfect for those with a taste for the extraordinary.', NULL, NULL, NULL, '一个时尚的机器陆行鸟，适合那些品味的非凡的人。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (13324, 'Red & Blue Mechanostrider', '', '', '', '红蓝机械陆行鸟', '', '', '', '', 'A striking combination of fiery red and cool blue, showcasing the power of opposites.', NULL, NULL, NULL, '“深蓝风”与“火红风”搭配，是冷与热的较量。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (23193, 'Armored Black Deathcharger', '', '', '', '黑色装甲亡灵战马', '', '', '', '', 'When fallen heroes are raised into undeath, so too are their horses.', NULL, NULL, NULL, '不朽的英雄复活为亡灵时，他们的马也复活了。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (21044, 'Winter Veil Reindeer', '', '', '', '冬幕节的麋鹿', '', '', '', '', 'Happy New Year, and Merry Winter Veil!', NULL, NULL, NULL, '新年快乐，冬天的冬幕节也很快乐！', NULL, NULL, NULL, NULL);
