INSERT INTO `locales_item` VALUES (84600, 'Blackthorn\'s Blackjack', '', '', '', '黑克索恩的21点', '', '', '', '', 'The time of origin remains a mystery.', NULL, NULL, NULL, '起源的时间仍然是个谜。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (84601, 'Grass of Eternity', '', '', '', '永恒之草', '', '', '', '', 'Even the grass surrounding the Well of Eternity was suffused with magic.', NULL, NULL, NULL, '就连永恒之井周围的草地也充满了魔力。', NULL, NULL, NULL, NULL);
