INSERT INTO `locales_item` VALUES (84603, 'Rod of the Churning Hourglass', '', '', '', '翻腾沙漏之杖', '', '', '', '', 'The past, the future and the grains of time lost in between.', NULL, NULL, NULL, '过去，未来和迷失在其间的时光', NULL, NULL, NULL, NULL);
