INSERT INTO `locales_item` VALUES (54000, 'Azure Frog', '', '', '', 'Azure的青蛙', '', '', '', '', 'A mystical amphibian known for its soothing croaks, said to bring tranquility to those who listen.', NULL, NULL, NULL, '这是一种神秘的两栖动物，以其舒缓的叫声而闻名，据说能给倾听的人带来安宁。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (54001, 'Dream Frog', '', '', '', '梦想的青蛙', '', '', '', '', 'This ethereal creature is believed to possess the ability to enter the dreams of sleeping adventurers, offering them guidance and wisdom.', NULL, NULL, NULL, '这种空灵的生物被认为拥有进入冒险家梦境的能力，为他们提供指引和智慧。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (54002, 'Bullfrog', '', '', '', '牛蛙', '', '', '', '', 'A robust amphibian with a powerful croak, often found near bodies of water, revered by some as a symbol of strength and resilience.', NULL, NULL, NULL, '一种强壮的两栖动物，叫声有力，经常出现在水体附近，被一些人视为力量和韧性的象征。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (54003, 'Infinite Frog', '', '', '', '无限的青蛙', '', '', '', '', 'A peculiar frog that seems to defy the laws of time and space, hopping effortlessly between dimensions.', NULL, NULL, NULL, '一种奇特的青蛙，似乎无视时间和空间法则，毫不费力地在不同维度之间跳跃。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (54004, 'Poison Frog', '', '', '', '毒蛙', '', '', '', '', 'Beware the vibrant hues of this deadly amphibian, as its skin secretes a potent toxin capable of incapacitating even the mightiest of foes.', NULL, NULL, NULL, '小心这种致命的两栖动物的鲜艳色彩，因为它的皮肤分泌一种强大的毒素，即使是最强大的敌人也能失去能力。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (54005, 'Snow Frog', '', '', '', '雪蛙', '', '', '', '', 'Native to the frigid regions of Azeroth, this hardy frog has adapted to survive in icy environments, its azure skin camouflaging it against the snowy landscapes.', NULL, NULL, NULL, '这种顽强的青蛙原产于艾泽拉斯的寒冷地区，它已经适应了在冰冷的环境中生存，它蔚蓝的皮肤使它在雪景中伪装起来。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (54006, 'Pink Frog', '', '', '', '粉红色的青蛙', '', '', '', '', 'Delicate and enchanting, this rare frog species captivates with its vibrant pink hue, believed to bring good fortune and prosperity to its owner.', NULL, NULL, NULL, '这种稀有的青蛙精致迷人，其鲜艳的粉红色吸引着人们，人们相信它会给主人带来好运和繁荣。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (54007, 'Golden Frog', '', '', '', '金蛙', '', '', '', '', 'Legend has it that this shimmering amphibian is a harbinger of wealth and abundance.', NULL, NULL, NULL, '传说这种闪闪发光的两栖动物是财富和富足的预兆。', NULL, NULL, NULL, NULL);
INSERT INTO `locales_item` VALUES (54008, 'Pond Frog', '', '', '', '池塘里的青蛙', '', '', '', '', 'A common sight in tranquil ponds and marshes, this unassuming frog is a reminder of the simple joys found in nature\'s embrace.', NULL, NULL, NULL, '在宁静的池塘和沼泽中，这只不起眼的青蛙是一种常见的景象，它提醒人们在大自然的怀抱中找到简单的快乐。', NULL, NULL, NULL, NULL);
